// PWM参数
// 设1kHz频率，占空比可调
// 72MHz / (71+1) / (999+1) = 1000Hz

// 初始占空比50%
// CCR = 500 → 50%

// 运行中修改占空比
__HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, 200);  // 改为20%
__HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, 800);  // 改为80%

// 获取当前占空比
uint32_t ccr = __HAL_TIM_GET_COMPARE(&htim2, TIM_CHANNEL_1);
float duty = (float)ccr / (htim2.Init.Period + 1) * 100;

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_TIM2_Init();

    // 启动PWM通道1
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);

    uint8_t duty = 0;
    while (1) {
        // 修改占空比
        __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, duty);
        duty = (duty + 10) % 100;
        HAL_Delay(50);
    }
}

// PWM呼吸灯
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_TIM2_Init();
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);

    while (1) {
        // 渐亮
        for (int i = 0; i <= 999; i += 10) {
            __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, i);
            HAL_Delay(10);
        }
        // 渐灭
        for (int i = 999; i >= 0; i -= 10) {
            __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, i);
            HAL_Delay(10);
        }
    }
}

/* 舵机控制

频率：50Hz，周期20ms
脉冲：0.5ms-2.5ms → 0°-180°

定时器配置(PSC=1439, ARR=9999)：
  72MHz / 1440 / 10000 = 50Hz
  20ms周期，1计数=2us

角度对应CCR：
  0°   → 0.5ms  → CCR=250
  90°  → 1.5ms  → CCR=750
  180° → 2.5ms  → CCR=1250
*/

// 设置舵机角度
void setServoAngle(int angle) {
    int ccr = 250 + angle * 1000 / 180;  // 0-180°→250-1250
    __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, ccr);
}

// 使用
setServoAngle(0);    // 0°
HAL_Delay(1000);
setServoAngle(90);   // 90°
HAL_Delay(1000);
setServoAngle(180);  // 180°

// 综合示例：多通道PWM
int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_TIM2_Init();

    // 启动多通道PWM
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_1);  // LED1
    HAL_TIM_PWM_Start(&htim2, TIM_CHANNEL_2);  // LED2

    uint16_t step = 0;
    while (1) {
        // LED1渐亮LED2渐灭
        __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_1, step);
        __HAL_TIM_SET_COMPARE(&htim2, TIM_CHANNEL_2, 999-step);
        step = (step + 10) % 1000;
        HAL_Delay(20);
    }
}
